import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import VRBuckets from "./components/VRBuckets";
import UseCaseIntake from "./components/UseCaseIntake";
import Modal from "./components/Modal";
import usecases from "./data/usecases.json";
import "./App.css";

function App() {
  const [selectedBucket, setSelectedBucket] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [activeView, setActiveView] = useState("buckets");

  // Handle clicking a bucket card
  const handleBucketClick = (bucket) => {
    setSelectedBucket(bucket);
    setShowModal(true);
  };

  // Close modal
  const closeModal = () => {
    setShowModal(false);
    setSelectedBucket(null);
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 text-gray-900">
      {/* Header */}
      <header className="bg-gradient-to-r from-blue-600 to-indigo-500 text-white py-6 shadow-md">
        <h1 className="text-2xl font-bold tracking-tight text-center">
          🎯 VR KPI Bucket App
        </h1>

        <div className="mt-4 flex justify-center gap-4">
          <button
            className={`px-4 py-2 rounded-lg border-2 transition-all ${
              activeView === "buckets"
                ? "bg-white text-blue-600 border-white"
                : "border-white text-white hover:bg-white hover:text-blue-600"
            }`}
            onClick={() => setActiveView("buckets")}
          >
            KPI Buckets
          </button>

          <button
            className={`px-4 py-2 rounded-lg border-2 transition-all ${
              activeView === "intake"
                ? "bg-white text-blue-600 border-white"
                : "border-white text-white hover:bg-white hover:text-blue-600"
            }`}
            onClick={() => setActiveView("intake")}
          >
            Use Case Intake
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 p-6">
        <AnimatePresence mode="wait">
          {activeView === "buckets" && (
            <motion.div
              key="buckets"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.4 }}
            >
              <VRBuckets onBucketClick={handleBucketClick} />
            </motion.div>
          )}

          {activeView === "intake" && (
            <motion.div
              key="intake"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.4 }}
            >
              <UseCaseIntake usecases={usecases} />
            </motion.div>
          )}
        </AnimatePresence>
      </main>

      {/* Modal for KPI Details */}
      {showModal && (
        <Modal onClose={closeModal} title={selectedBucket?.name}>
          <div className="text-left space-y-3">
            <p className="text-sm text-gray-600">
              {selectedBucket?.description}
            </p>

            <ul className="list-disc pl-6 text-gray-800">
              {selectedBucket?.kpis?.map((kpi, i) => (
                <li key={i}>
                  <strong>{kpi.name}</strong> – {kpi.description}
                </li>
              ))}
            </ul>
          </div>
        </Modal>
      )}

      {/* Footer */}
      <footer className="bg-gray-900 text-gray-200 py-4 text-sm text-center">
        <p>
          Built with ❤️ by <strong>Thomas Dee</strong> — powered by Adobe’s
          Value Framework
        </p>
      </footer>
    </div>
  );
}

export default App;






















